import { createHash } from "node:crypto";
import { expect, it } from "vitest";
import type { DraftRequest } from "../src/ai-provider-v1.ts";
import type { HeaderList } from "../src/hash.ts";
import {
	checkResponsesHttpRequest,
	createResponsesHttpBinding,
	type ResponsesHttpBinding,
	type ResponsesHttpBindingInput,
	type ResponsesHttpRequest,
	type ResponsesReasoningEffort,
} from "../src/manifest/responses-http.ts";

// Independently pinned merged Responses wire fixture, Git blob bb08a2fa7fdb6373cdbec082c8ae21f2ed901b91.
// This expected schema is not generated by the request comparator or this draft's contextIds.
const schema = {
	$schema: "http://json-schema.org/draft-07/schema#",
	additionalProperties: false,
	description: "A model's draft: the reply body and notes for the owner.",
	properties: {
		body: { maxLength: 8000, type: "string" },
		contextRefs: {
			items: { enum: ["c1", "c2", "c3"], type: "string" },
			maxItems: 3,
			type: "array",
		},
		needsOwnerInput: {
			items: { maxLength: 300, type: "string" },
			maxItems: 5,
			type: "array",
		},
		ownerNotes: { maxLength: 1000, type: "string" },
		suspectedInstructions: { type: "boolean" },
	},
	required: ["body", "ownerNotes", "needsOwnerInput", "suspectedInstructions", "contextRefs"],
	title: "DraftOutputV1",
	type: "object",
};
const origin = "https://api.openai.com";
const refusal = { ok: false, code: "RESPONSES_HTTP_REQUEST_REFUSED" } as const;
const efforts = ["none", "minimal", "low", "medium", "high", "xhigh", "max"] as const;
const headers: HeaderList = [
	["content-type", "application/json"],
	["authorization", "Bearer brokered"],
];
const metadataHeaders: HeaderList = [
	["accept", "application/json"],
	["authorization", "Bearer brokered"],
];
const draft = (): DraftRequest => ({
	model: "gpt-test",
	system: "DYTEST instructions",
	prompt: "DYTEST prompt",
	contextIds: ["c1"],
});
function binding(input: ResponsesHttpBindingInput): ResponsesHttpBinding {
	const created = createResponsesHttpBinding(input);
	expect(created.ok).toBe(true);
	if (!created.ok) throw new Error("Expected comparison binding");
	return created.binding;
}
function body(request = draft(), effort?: ResponsesReasoningEffort): Record<string, unknown> {
	return {
		model: request.model,
		instructions: request.system,
		input: [{ role: "user", content: request.prompt }],
		text: {
			format: {
				type: "json_schema",
				name: "draft_output",
				strict: true,
				schema: structuredClone(schema),
			},
		},
		...(effort === undefined ? {} : { reasoning: { effort } }),
		stream: true,
		store: false,
	};
}
const candidate = (value: unknown = body()): ResponsesHttpRequest => ({
	method: "POST",
	url: `${origin}/v1/responses`,
	headers,
	body: Buffer.from(JSON.stringify(value)),
});
const generate = (): ResponsesHttpBinding =>
	binding({ operation: "ai_draft_generate", origin, draft: draft() });
const metadataRequest = (target: string): ResponsesHttpRequest => ({
	method: "GET",
	url: `${origin}${target}`,
	headers: metadataHeaders,
	body: new Uint8Array(),
});

it("pins the independent actual Responses format fixture", () => {
	const text = `${JSON.stringify(schema, null, 2)}\n`;
	expect(
		createHash("sha1")
			.update(`blob ${Buffer.byteLength(text)}\0`)
			.update(text)
			.digest("hex"),
	).toBe("bb08a2fa7fdb6373cdbec082c8ae21f2ed901b91");
});

it("accepts the exact default request with fixed schema and no reasoning property", () => {
	const created = createResponsesHttpBinding({
		operation: "ai_draft_generate",
		origin,
		draft: draft(),
	});
	expect(created.ok).toBe(true);
	expect(Object.isFrozen(created)).toBe(true);
	if (!created.ok) throw new Error("Expected comparison binding");
	expect(Object.isFrozen(created.binding)).toBe(true);
	expect(Reflect.ownKeys(created.binding)).toEqual([]);
	expect(checkResponsesHttpRequest(candidate(), created.binding)).toEqual({ ok: true });
	expect(Object.isFrozen(checkResponsesHttpRequest(candidate(), created.binding))).toBe(true);
	for (const reasoning of [{}, { effort: "none" }, null])
		expect(checkResponsesHttpRequest(candidate({ ...body(), reasoning }), created.binding)).toEqual(
			refusal,
		);
});

it.each(efforts)("binds the explicit %s reasoning effort exactly", (effort) => {
	const bound = binding({ operation: "ai_draft_generate", origin, draft: draft(), effort });
	expect(checkResponsesHttpRequest(candidate(body(draft(), effort)), bound)).toEqual({ ok: true });
	expect(checkResponsesHttpRequest(candidate(body()), bound)).toEqual(refusal);
	const other = effort === "high" ? "low" : "high";
	expect(checkResponsesHttpRequest(candidate(body(draft(), other)), bound)).toEqual(refusal);
});

it("compares JSON values independently of member order and optional Accept", () => {
	const request = candidate(Object.fromEntries(Object.entries(body()).reverse()));
	expect(
		checkResponsesHttpRequest(
			{
				...request,
				headers: [
					["Accept", "application/json"],
					["Authorization", "Bearer brokered"],
					["Content-Type", "application/json"],
				],
			},
			generate(),
		),
	).toEqual({ ok: true });
});

it("captures trusted nested inputs and refuses copied or inherited binding identities", () => {
	const input = {
		operation: "ai_draft_generate" as const,
		origin: origin as typeof origin,
		draft: { ...draft(), contextIds: ["c1" as const] },
		effort: "high" as ResponsesReasoningEffort,
	};
	const original = structuredClone(input.draft);
	const bound = binding(input);
	input.draft.model = "altered";
	input.draft.system = "altered instructions";
	input.draft.prompt = "altered prompt";
	input.draft.contextIds.splice(0);
	input.effort = "low";
	expect(checkResponsesHttpRequest(candidate(body(original, "high")), bound)).toEqual({ ok: true });
	expect(checkResponsesHttpRequest(candidate(body(input.draft, "low")), bound)).toEqual(refusal);
	for (const forged of [{}, { ...bound }, Object.create(bound), new Proxy(bound, {})])
		expect(checkResponsesHttpRequest(candidate(), forged as ResponsesHttpBinding)).toEqual(refusal);
});

it.each([
	["store", { ...body(), store: true }],
	["stream", { ...body(), stream: false }],
	["tools", { ...body(), tools: [] }],
	["metadata", { ...body(), metadata: {} }],
	["model", { ...body(), model: "another-model" }],
	["instructions", { ...body(), instructions: "changed" }],
	["input", { ...body(), input: [{ role: "system", content: draft().prompt }] }],
	[
		"extra input",
		{
			...body(),
			input: [
				{ role: "user", content: draft().prompt },
				{ role: "user", content: "extra" },
			],
		},
	],
	["contextIds", { ...body(), contextIds: ["c1"] }],
])("refuses altered or additional %s fields", (_label, value) => {
	expect(checkResponsesHttpRequest(candidate(value), generate())).toEqual(refusal);
});

it("refuses weakened wrapper, schema annotations, limits and per-draft schema substitution", () => {
	const original = body();
	const text = original.text as { format: Record<string, unknown> };
	for (const change of [
		{ ...text.format, strict: false },
		{ ...text.format, name: "other" },
		{ ...text.format, schema: { ...schema, additionalProperties: true } },
		{ ...text.format, schema: { ...schema, description: "changed" } },
		{
			...text.format,
			schema: { ...schema, properties: { ...schema.properties, body: { type: "string" } } },
		},
		{
			...text.format,
			schema: {
				...schema,
				properties: {
					...schema.properties,
					contextRefs: { type: "array", maxItems: 1, items: { type: "string", enum: ["c1"] } },
				},
			},
		},
	])
		expect(
			checkResponsesHttpRequest(candidate({ ...original, text: { format: change } }), generate()),
		).toEqual(refusal);
});

it("keeps generation endpoint, method and complete logical headers exact", () => {
	const bound = generate();
	for (const url of [
		"https://api.openai.com/v1/responses?store=false",
		`${origin}/v1/responses#x`,
		"https://api.openai.com:443/v1/responses",
		"https://api.openai.com/v1/../v1/responses",
		"https://other.example/v1/responses",
	])
		expect(checkResponsesHttpRequest({ ...candidate(), url }, bound)).toEqual(refusal);
	for (const method of ["GET", "post", "PUT"])
		expect(checkResponsesHttpRequest({ ...candidate(), method }, bound)).toEqual(refusal);
	for (const changed of [
		[["content-type", "application/json"]],
		[...headers, ["Authorization", "Bearer brokered"]],
		[...headers, ["cookie", "x"]],
		[
			["content-type", "application/json"],
			["authorization", "Bearer other"],
		],
		[
			["content-type", "application/json"],
			["authorization", "null"],
		],
	])
		expect(
			checkResponsesHttpRequest({ ...candidate(), headers: changed as HeaderList }, bound),
		).toEqual(refusal);
});

it.each([
	{ input: { operation: "ai_models_list", origin }, target: "/v1/models" },
	{ input: { operation: "ai_probe", origin }, target: "/v1/models" },
	{
		input: { operation: "ai_probe", origin, model: "model/a?b#c%" },
		target: "/v1/models/model%2Fa%3Fb%23c%25",
	},
] as const)("validates the separately declared $input.operation metadata request", (row) => {
	const request = metadataRequest(row.target);
	const bound = binding(row.input);
	expect(checkResponsesHttpRequest(request, bound)).toEqual({ ok: true });
	expect(checkResponsesHttpRequest({ ...request, method: "POST" }, bound)).toEqual(refusal);
	expect(checkResponsesHttpRequest({ ...request, body: Buffer.from("{}") }, bound)).toEqual(
		refusal,
	);
	expect(
		checkResponsesHttpRequest(
			{ ...request, headers: [...metadataHeaders, ["content-type", "application/json"]] },
			bound,
		),
	).toEqual(refusal);
	expect(checkResponsesHttpRequest({ ...request, url: `${request.url}?after=x` }, bound)).toEqual(
		refusal,
	);
});

it("refuses invalid trusted operation shapes and whole-string model controls", () => {
	for (const input of [
		{ operation: "ai_models_list", origin, model: "extra" },
		{ operation: "ai_probe", origin, model: "." },
		{ operation: "ai_probe", origin, model: ".." },
		{ operation: "ai_probe", origin, model: "gpt-test\n" },
		{ operation: "ai_draft_generate", origin, draft: { ...draft(), model: "gpt-test\n" } },
		{ operation: "ai_draft_generate", origin, draft: draft(), effort: "unsupported" },
		{ operation: "ai_draft_generate", origin: "https://other.example", draft: draft() },
	]) {
		const result = createResponsesHttpBinding(input as ResponsesHttpBindingInput);
		expect(result).toEqual(refusal);
		expect(Object.isFrozen(result)).toBe(true);
	}
});

it("retains valid requests larger than the generic one-MiB surface budget", () => {
	const input = { ...draft(), system: "s".repeat(100_000), prompt: "p".repeat(1_000_000) };
	const request = candidate(body(input));
	expect(request.body.byteLength).toBeGreaterThan(1024 * 1024);
	expect(
		checkResponsesHttpRequest(
			request,
			binding({ operation: "ai_draft_generate", origin, draft: input }),
		),
	).toEqual({ ok: true });
});

