it("pins one metadata wire suffix for each visible-ASCII character", () => {
	expect(metadataWireSuffixes).toHaveLength(0x7e - 0x20);
});

it.each(
	metadataWireSuffixes.map((suffix, index) => [String.fromCharCode(0x21 + index), suffix] as const),
)("binds the literal metadata wire target for DYTEST-%s", (character, suffix) => {
	const escaped = `%${character.charCodeAt(0).toString(16).toUpperCase()}`;
	expect([character, escaped]).toContain(suffix);
	const bound = binding({ operation: "ai_probe", origin, model: `DYTEST-${character}` });
	expect(checkResponsesHttpRequest(metadataRequest(`/v1/models/DYTEST-${suffix}`), bound)).toEqual({
		ok: true,
	});
	const other = suffix === character ? escaped : character;
	expect(checkResponsesHttpRequest(metadataRequest(`/v1/models/DYTEST-${other}`), bound)).toEqual(
		refusal,
	);
});

it.each([
	// The first target is the one the API-key client's metadata fake records.
	[
		"gpt-synthetic/a?b=%25#d+e",
		"gpt-synthetic%2Fa%3Fb=%2525%23d+e",
		"gpt-synthetic%2Fa%3Fb%3D%2525%23d%2Be",
	],
	["ft:dytest@a$b&c+d,e;f=g", "ft:dytest@a$b&c+d,e;f=g", "ft%3Adytest%40a%24b%26c%2Bd%2Ce%3Bf%3Dg"],
	["...", "...", "%2E%2E%2E"],
] as const)("binds the literal metadata wire target for %s", (model, target, refused) => {
	const bound = binding({ operation: "ai_probe", origin, model });
	expect(checkResponsesHttpRequest(metadataRequest(`/v1/models/${target}`), bound)).toEqual({
		ok: true,
	});
	expect(checkResponsesHttpRequest(metadataRequest(`/v1/models/${refused}`), bound)).toEqual(
		refusal,
	);
});
